// Converts Campsite's React icon set into a static data module for Icon.svelte.
//
// Usage: node scripts/icons-from-campsite.js <path to packages/ui/src/Icons/index.tsx>
//
// Reads every `export function XIcon(props) { ... return (<svg ...>...</svg>) }` and writes
// src/lib/components/ui/icons/campsite-icons.ts. JSX attributes become plain SVG attributes and
// `{strokeWidth}` becomes the `{sw}` placeholder that Icon.svelte substitutes. Icons whose markup
// cannot be converted statically are skipped and listed at the top of the generated file.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HEADER =
	'// Adapted from Campsite (https://github.com/campsite/campsite), packages/ui/src/Icons/index.tsx, commit cc14551, modified. Licensed CC BY-NC 4.0: https://creativecommons.org/licenses/by-nc/4.0/';
const GENERATED = '// Generated by scripts/icons-from-campsite.js; do not edit by hand.';
const DEFAULT_STROKE_WIDTH = '1.5';

// SVG attributes that are camelCase in SVG itself and must keep their case.
const SVG_CAMEL_ATTRS = new Set([
	'viewBox',
	'preserveAspectRatio',
	'gradientUnits',
	'gradientTransform',
	'patternUnits',
	'patternContentUnits',
	'patternTransform',
	'maskUnits',
	'maskContentUnits',
	'clipPathUnits',
	'filterUnits',
	'primitiveUnits',
	'stdDeviation',
	'markerWidth',
	'markerHeight',
	'markerUnits',
	'refX',
	'refY',
	'pathLength',
	'spreadMethod',
	'startOffset',
	'textLength',
	'lengthAdjust',
	'baseFrequency',
	'numOctaves',
	'tableValues',
	'kernelMatrix',
	'kernelUnitLength',
	'diffuseConstant',
	'specularConstant',
	'specularExponent',
	'surfaceScale',
	'edgeMode',
	'xChannelSelector',
	'yChannelSelector',
	'attributeName',
	'repeatCount',
	'keyTimes',
	'keySplines',
	'calcMode'
]);

const SPECIAL_ATTRS = {
	className: 'class',
	htmlFor: 'for',
	xlinkHref: 'xlink:href',
	xmlSpace: 'xml:space',
	xmlLang: 'xml:lang',
	xmlnsXlink: 'xmlns:xlink'
};

function kebab(name) {
	return name
		.replace(/([a-z0-9])([A-Z])/g, '$1-$2')
		.replace(/([A-Z])([A-Z][a-z])/g, '$1-$2')
		.toLowerCase();
}

function iconKey(fnName) {
	return kebab(fnName.replace(/Icon$/, ''));
}

function convertAttrName(name) {
	if (name in SPECIAL_ATTRS) return SPECIAL_ATTRS[name];
	if (SVG_CAMEL_ATTRS.has(name)) return name;
	if (name.includes('-') || !/[A-Z]/.test(name)) return name;
	return kebab(name);
}

function escapeAttr(value) {
	return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

/**
 * Converts a JSX expression in attribute position to a static attribute value.
 * Returns null when the expression is not static.
 */
function staticExpression(expr) {
	const e = expr.trim();
	if (e === 'strokeWidth') return '{sw}';
	if (/^-?\d+(\.\d+)?$/.test(e)) return e;
	const str = /^(['"`])([^'"`$]*)\1$/.exec(e);
	if (str) return str[2];
	return null;
}

/** Returns the index just past the `}` that closes the `{` at `start`. */
function matchBrace(src, start) {
	let depth = 0;
	for (let i = start; i < src.length; i++) {
		const c = src[i];
		if (c === "'" || c === '"' || c === '`') {
			const end = src.indexOf(c, i + 1);
			if (end === -1) return -1;
			i = end;
		} else if (c === '{') depth++;
		else if (c === '}') {
			depth--;
			if (depth === 0) return i + 1;
		}
	}
	return -1;
}

/**
 * Converts a JSX tag's attribute string. Throws with a reason when it can't.
 * `fallbacks` collects attributes that were dropped in favour of their static default.
 */
function convertAttrs(attrSrc, fallbacks) {
	const out = [];
	let i = 0;
	while (i < attrSrc.length) {
		const ws = /^\s+/.exec(attrSrc.slice(i));
		if (ws) {
			i += ws[0].length;
			continue;
		}
		if (attrSrc.startsWith('/', i)) {
			i++;
			continue;
		}
		if (attrSrc[i] === '{') {
			const end = matchBrace(attrSrc, i);
			throw new Error(`spread or expression attribute ${attrSrc.slice(i, end)}`);
		}
		const nameMatch = /^[A-Za-z_:][\w:.-]*/.exec(attrSrc.slice(i));
		if (!nameMatch) throw new Error(`unexpected attribute text near "${attrSrc.slice(i, i + 20)}"`);
		const name = nameMatch[0];
		i += name.length;
		if (attrSrc[i] !== '=') {
			out.push(convertAttrName(name));
			continue;
		}
		i++;
		const q = attrSrc[i];
		let value;
		if (q === "'" || q === '"') {
			const end = attrSrc.indexOf(q, i + 1);
			value = attrSrc.slice(i + 1, end);
			i = end + 1;
		} else if (q === '{') {
			const end = matchBrace(attrSrc, i);
			const expr = attrSrc.slice(i + 1, end - 1);
			i = end;
			value = staticExpression(expr);
			if (value === null) {
				// An animation-only class (`isAnimated ? '...' : ''`) has an empty static default.
				if (/^\s*isAnimated\s*\?[\s\S]*:\s*(''|"")\s*$/.test(expr)) {
					fallbacks.push(`${name}={isAnimated ? ... : ''}`);
					continue;
				}
				throw new Error(`dynamic expression ${name}={${expr.trim().replace(/\s+/g, ' ')}}`);
			}
		} else {
			throw new Error(`unquoted attribute value for ${name}`);
		}
		out.push(`${convertAttrName(name)}="${escapeAttr(value)}"`);
	}
	return out.join(' ');
}

/** Converts the inner JSX of an <svg> element to SVG markup. Throws when it can't. */
function convertBody(jsx, fallbacks) {
	let out = '';
	let i = 0;
	while (i < jsx.length) {
		const c = jsx[i];
		if (c === '<') {
			if (jsx.startsWith('</', i)) {
				const end = jsx.indexOf('>', i);
				out += `</${jsx.slice(i + 2, end).trim()}>`;
				i = end + 1;
				continue;
			}
			const nameMatch = /^<([A-Za-z][\w.:-]*)/.exec(jsx.slice(i));
			if (!nameMatch) throw new Error(`unexpected "<" near "${jsx.slice(i, i + 20)}"`);
			const tag = nameMatch[1];
			if (/^[A-Z]/.test(tag) || tag.includes('.')) throw new Error(`component <${tag}>`);
			// Find the end of the tag, skipping quoted strings and braces.
			let j = i + nameMatch[0].length;
			while (j < jsx.length && jsx[j] !== '>') {
				const ch = jsx[j];
				if (ch === "'" || ch === '"') j = jsx.indexOf(ch, j + 1) + 1;
				else if (ch === '{') j = matchBrace(jsx, j);
				else j++;
				if (j <= 0) throw new Error(`unterminated <${tag}>`);
			}
			const raw = jsx.slice(i + nameMatch[0].length, j);
			const selfClosing = /\/\s*$/.test(raw);
			const attrs = convertAttrs(raw.replace(/\/\s*$/, ''), fallbacks);
			out += `<${tag}${attrs ? ' ' + attrs : ''}${selfClosing ? ' />' : '>'}`;
			i = j + 1;
		} else if (c === '{') {
			const end = matchBrace(jsx, i);
			const expr = jsx.slice(i + 1, end - 1).trim();
			if (/^\/\*[\s\S]*\*\/$/.test(expr)) {
				i = end;
				continue;
			}
			throw new Error(`child expression {${expr.replace(/\s+/g, ' ').slice(0, 60)}}`);
		} else {
			const next = jsx.slice(i).search(/[<{]/);
			const text = next === -1 ? jsx.slice(i) : jsx.slice(i, i + next);
			if (text.trim()) out += text.trim();
			i += text.length;
		}
	}
	return out;
}

function parseIcons(src) {
	const icons = [];
	const skipped = [];
	const fnRe = /^export function (\w+)\s*\(([^)]*)\)\s*\{$/gm;
	const starts = [...src.matchAll(fnRe)];
	for (const [n, m] of starts.entries()) {
		const fnName = m[1];
		const bodyEnd = n + 1 < starts.length ? starts[n + 1].index : src.length;
		const fnSrc = src.slice(m.index, bodyEnd);
		const fallbacks = [];
		try {
			const svgStart = fnSrc.indexOf('<svg');
			const svgEnd = fnSrc.lastIndexOf('</svg>');
			if (svgStart === -1 || svgEnd === -1) throw new Error('no <svg> element');
			const beforeSvg = fnSrc.slice(0, svgStart);
			if (/\bif\s*\(|\?|&&|\.map\(/.test(beforeSvg.replace(/\(props: \w+\)/, ''))) {
				throw new Error('logic before the returned <svg>');
			}

			// Opening <svg ...> tag.
			let j = svgStart + 4;
			while (fnSrc[j] !== '>') {
				const ch = fnSrc[j];
				if (ch === "'" || ch === '"') j = fnSrc.indexOf(ch, j + 1) + 1;
				else if (ch === '{') j = matchBrace(fnSrc, j);
				else j++;
			}
			const svgAttrSrc = fnSrc.slice(svgStart + 4, j);
			const svgAttrs = {};
			for (const a of svgAttrSrc.matchAll(/(\w+)=(?:'([^']*)'|"([^"]*)"|\{([^}]*)\})/g)) {
				svgAttrs[a[1]] = a[4] === undefined ? (a[2] ?? a[3]) : staticExpression(a[4]);
			}

			const viewBox = svgAttrs.viewBox;
			if (!viewBox || viewBox.trim().split(/[\s,]+/).length !== 4) throw new Error('no viewBox');

			const sizeDefault = /\bsize\s*=\s*(\d+)/.exec(beforeSvg);
			let size = sizeDefault ? Number(sizeDefault[1]) : Number(svgAttrs.width);
			if (!Number.isFinite(size) || size <= 0) size = 20;

			const swDefault = /\bstrokeWidth\s*=\s*'?([\d.]+)'?/.exec(beforeSvg);
			const strokeWidth = swDefault ? swDefault[1] : DEFAULT_STROKE_WIDTH;

			let body = convertBody(fnSrc.slice(j + 1, svgEnd), fallbacks);
			if (!body) throw new Error('empty body');
			// A nested <svg> that only repeats the outer viewport is redundant; keep its children.
			const [, , vbW, vbH] = viewBox.trim().split(/[\s,]+/);
			const nested = /^<svg ([^>]*)>([\s\S]*)<\/svg>$/.exec(body);
			if (nested) {
				const attrs = Object.fromEntries(
					[...nested[1].matchAll(/([\w:-]+)="([^"]*)"/g)].map((a) => [a[1], a[2]])
				);
				const redundant =
					attrs.viewBox === viewBox &&
					attrs.width === vbW &&
					attrs.height === vbH &&
					Object.keys(attrs).every((k) =>
						['width', 'height', 'viewBox', 'fill', 'xmlns'].includes(k)
					) &&
					(attrs.fill ?? 'none') === 'none';
				if (!redundant) throw new Error('nested <svg> with its own viewport');
				body = nested[2];
				fallbacks.push('redundant nested <svg>');
			}
			if (body.includes('<svg')) throw new Error('nested <svg>');
			// Presentation attributes on the root <svg> other than fill="none" move to a group.
			const rootPaint = Object.entries(svgAttrs)
				.filter(
					([k, v]) =>
						['fill', 'stroke', 'strokeWidth', 'color'].includes(k) &&
						!(k === 'fill' && v === 'none')
				)
				.map(([k, v]) => {
					if (v === null) throw new Error(`dynamic ${k} on <svg>`);
					return `${convertAttrName(k)}="${escapeAttr(v)}"`;
				});
			if (rootPaint.length) body = `<g ${rootPaint.join(' ')}>${body}</g>`;

			icons.push({ fnName, key: iconKey(fnName), viewBox, size, strokeWidth, body, fallbacks });
		} catch (err) {
			skipped.push({ fnName, reason: err.message });
		}
	}
	return { icons, skipped };
}

function render({ icons, skipped }) {
	const lines = [HEADER, GENERATED, '//'];
	if (skipped.length) {
		lines.push('// Skipped (markup not convertible to static SVG):');
		for (const s of skipped) lines.push(`//   ${s.fnName}: ${s.reason}`);
	} else {
		lines.push('// Skipped: none.');
	}
	const withFallback = icons.filter((i) => i.fallbacks.length);
	if (withFallback.length) {
		lines.push(
			'// Converted to their static form (animation classes and redundant wrappers dropped):'
		);
		for (const i of withFallback) lines.push(`//   ${i.fnName}: dropped ${i.fallbacks.join(', ')}`);
	}
	lines.push(
		'',
		'export interface IconData {',
		'\tviewBox: string;',
		'\t/** Inner SVG markup; `{sw}` stands for the stroke width. */',
		'\tbody: string;',
		'\t/** Default width and height in pixels. */',
		'\tsize: number;',
		"\t/** Default stroke width when it isn't '1.5'. */",
		'\tstrokeWidth?: string;',
		'}',
		'',
		'export const icons = {'
	);
	// Emitted in the repository's Prettier style so regenerating gives a clean diff.
	const quote = (s) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
	for (const icon of icons) {
		const key = /^[A-Za-z_$][\w$]*$/.test(icon.key) ? icon.key : quote(icon.key);
		lines.push(`	${key}: {`, `		viewBox: ${quote(icon.viewBox)},`, `		size: ${icon.size},`);
		if (icon.strokeWidth !== DEFAULT_STROKE_WIDTH) {
			lines.push(`		strokeWidth: ${quote(icon.strokeWidth)},`);
		}
		lines.push(`		body: ${quote(icon.body)}`, '	},');
	}
	lines[lines.length - 1] = '	}';
	lines.push(
		'} satisfies Record<string, IconData>;',
		'',
		'export type IconName = keyof typeof icons;',
		''
	);
	return lines.join('\n');
}

const input = process.argv[2];
if (!input) {
	console.error('Usage: node scripts/icons-from-campsite.js <path to Icons/index.tsx>');
	process.exit(1);
}
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outFile = resolve(root, 'src/lib/components/ui/icons/campsite-icons.ts');

const result = parseIcons(readFileSync(input, 'utf8'));
const seen = new Map();
result.icons = result.icons.filter((icon) => {
	if (seen.has(icon.key)) {
		result.skipped.push({
			fnName: icon.fnName,
			reason: `duplicate key '${icon.key}' (${seen.get(icon.key)})`
		});
		return false;
	}
	seen.set(icon.key, icon.fnName);
	return true;
});

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, render(result));
console.log(`Wrote ${result.icons.length} icons to ${outFile}`);
for (const s of result.skipped) console.log(`Skipped ${s.fnName}: ${s.reason}`);
for (const i of result.icons.filter((i) => i.fallbacks.length)) {
	console.log(`Static fallback ${i.fnName}: dropped ${i.fallbacks.join(', ')}`);
}
